function setup() {
  createCanvas(windowWidth, windowHeight);
  noStroke();
}

function draw() {
  background(0, 20);
  fill(255, 180, 60);
  const cx = width / 2;
  const cy = height / 2;
  for (let i = 0; i < 8; i++) {
    const a = (beat * 0.2 + i * TWO_PI / 8);
    const r = 200 + 40 * sin(frameCount * 0.02 + i);
    ellipse(cx + cos(a) * r, cy + sin(a) * r, 40, 40);
  }
}

let agents = [];

function setup() {
  createCanvas(windowWidth, windowHeight);
  background(0);
  for (let i = 0; i < 200; i++) {
    agents.push({ x: random(width), y: random(height) });
  }
}

function draw() {
  noStroke();
  fill(0, 8);
  rect(0, 0, width, height);
  fill(120, 200, 255, 120);
  for (const a of agents) {
    const n = noise(a.x * 0.003, a.y * 0.003, frameCount * 0.005);
    const ang = n * TWO_PI * 2;
    a.x += cos(ang) * 1.2;
    a.y += sin(ang) * 1.2;
    if (a.x < 0) a.x = width;
    if (a.x > width) a.x = 0;
    if (a.y < 0) a.y = height;
    if (a.y > height) a.y = 0;
    ellipse(a.x, a.y, 2, 2);
  }
}
